from collections import deque
rooms = {"class": ["hall"], "hall": ["class", "library"], "library": ["hall"]}
queue = deque(["class"])
seen = {"class"}
order = []
while queue:
    room = queue.popleft()
    order.append(room)
    for next_room in rooms[room]:
        if next_room not in seen:
            seen.add(next_room)
            queue.append(next_room)
print(order)
